/* Lead detail: action-first. Status pipeline, follow-up strip, composer (Email / Call / Meeting / Research), timeline,
   contact + company cards you can act from. */
(function () {
  const { esc, dash, fmtDate, fmtDT, rel, badge, prio, userLabel, opts, I, timeline, modal, toast, form } = UI;
  const db = () => Store.db;
  const STAGES = ['New', 'Not Contacted', 'Contacted', 'Interested', 'Qualified', 'Proposal Sent', 'Negotiation', 'Won'];
  const CLOSED = ['Lost', 'Not Relevant'];
  const TPL = {
    intro: ['Intro call this week?', 'Hi {first},\n\nThanks for getting in touch with DAIT Partners. I\'d love to hear more about what you\'re working on at {company}. Would a 30-minute call this week suit you?\n\nBest regards,\n{me}'],
    followup: ['Following up', 'Hi {first},\n\nJust checking in after our last conversation. Is there anything you need from me to move things forward at {company}?\n\nBest regards,\n{me}'],
    proposal: ['Our proposal for {company}', 'Hi {first},\n\nPlease find our proposal attached. Happy to walk you through it whenever convenient.\n\nBest regards,\n{me}'],
    thanks: ['Thank you for your time', 'Hi {first},\n\nThank you for your time today. As discussed, I\'ll send over the next steps shortly.\n\nBest regards,\n{me}'],
  };

  V.leadDetail = function (id, tab) {
    const l = Store.lead(id); if (!l) return { html: topbar('Lead not found') + '<div class="page"><div class="empty">No lead with id ' + esc(id) + '. <a href="#/leads">Back to leads</a></div></div>' };
    tab = tab || 'all';
    const me = Store.currentUser(); const t = Store.today();
    const c = Store.company(l.companyId); const ct = Store.contact(l.contactId); const enq = l.enquiryId ? db().enquiries.find((e) => e.id === l.enquiryId) : null;
    const acts = db().activities.filter((a) => a.leadId === id).sort((a, b) => (a.at < b.at ? 1 : -1));
    const tasks = db().tasks.filter((x) => x.leadId === id && !x.done).sort((a, b) => (a.due > b.due ? 1 : -1));
    const quotes = db().quotes.filter((x) => x.leadId === id); const events = db().events.filter((e) => e.leadId === id && e.date >= t).sort((a, b) => (a.date > b.date ? 1 : -1));
    const research = acts.filter((a) => a.type === 'research');
    const contacts = db().contacts.filter((x) => x.companyId === l.companyId);
    const others = db().leads.filter((x) => x.companyId === l.companyId && x.id !== id);
    const over = l.followUp && l.followUp < t && !CLOSED.concat('Won').includes(l.status);
    const first = ct ? ct.firstName : (l.companyName.split(' ')[0]);
    const fill = (s) => s.replace(/\{first\}/g, first).replace(/\{company\}/g, l.companyName).replace(/\{me\}/g, me.name);
    const idx = STAGES.indexOf(l.status); const isClosed = CLOSED.includes(l.status);
    const FILTERS = [['all', 'All', acts.length], ['email', 'Emails', acts.filter((a) => a.type === 'email').length], ['call', 'Calls', acts.filter((a) => a.type === 'call').length], ['meeting', 'Meetings', acts.filter((a) => a.type === 'meeting').length], ['research', 'Research', research.length], ['system', 'System', acts.filter((a) => ['assign', 'transfer', 'ai', 'created', 'status'].includes(a.type)).length]];
    const shown = tab === 'all' ? acts : tab === 'system' ? acts.filter((a) => ['assign', 'transfer', 'ai', 'created', 'status'].includes(a.type)) : acts.filter((a) => a.type === tab);
    const email = l.email || (ct && ct.email) || ''; const phone = l.phone || (ct && (ct.mobile || ct.phone)) || '';

    /* Header: lead (contact) name + small lead ID, then designation · company, city, country · lead type tag.
       Source and priority are shown in the page body. With no contact yet, the company name is the title. */
    const where = [l.companyName, l.city, l.country].filter(Boolean).join(', ');
    const header = topbar(esc(ct ? ct.firstName + ' ' + ct.lastName : l.companyName) + ' <span style="font-size:13px;font-weight:500;color:var(--muted)">' + id + '</span>',
      (ct ? (ct.designation ? esc(ct.designation) + ' · ' : '') + esc(where) : '<span class="dim">No contact yet</span>' + ([l.city, l.country].some(Boolean) ? ' · ' + esc([l.city, l.country].filter(Boolean).join(', ')) : '')) + ' · ' + badge(l.type),
      '<div class="hdr-actions"><button class="btn primary" data-compose="email">' + I.send + 'Email</button><button class="btn" data-compose="call">' + I.phoneC + 'Log call</button><button class="btn" data-compose="meeting">' + I.calC + 'Schedule</button><button class="btn" data-act="edit">' + I.edit + 'Edit lead</button><button class="btn" data-act="clone">' + I.copy + 'Clone lead</button></div>', '<a href="#/leads">Leads</a> / ' + id);

    const stepper = isClosed ? '<div class="closed-banner"><strong>' + esc(l.status) + '</strong><span>This lead is closed. Status changes and reasons stay in the timeline.</span><div class="grow"></div><button class="btn sm" data-stage="Contacted">Reopen</button></div>' :
      '<div class="stepper">' + STAGES.map((s, i) => '<button class="stage' + (i < idx ? ' done' : i === idx ? ' on' : '') + '" data-stage="' + s + '" title="Set status to ' + s + '"><div class="bar"></div><div class="t">' + s + '</div></button>').join('') + '<button class="stage closed" data-act="close" style="flex:0 0 auto;min-width:96px"><div class="bar" style="background:var(--line)"></div><div class="t" style="color:var(--muted);font-weight:500">Lost / not relevant ▾</div></button></div>';

    const ctrl = '<div class="ctrl"><div style="min-width:260px;max-width:300px"><span class="l">Next follow-up</span><div style="display:flex;gap:8px;align-items:center"><input class="in" type="date" name="followUp" value="' + (l.followUp || '') + '" style="width:160px' + (over ? ';border-color:var(--bad-fg)' : '') + '">' + (over ? badge('Overdue', 'b-bad') : l.followUp ? badge(fmtDate(l.followUp) === fmtDate(t) ? 'Today' : 'Scheduled', 'b-purple') : '') + '</div><div class="quick"><button data-q="1">Tomorrow</button><button data-q="4">+4 days</button><button data-q="7">Next week</button></div></div>' +
      '<div style="max-width:220px"><span class="l">Owner</span><select class="in" name="assignedTo"><option value="">Unassigned</option>' + opts(db().users.map((u) => ({ value: u.id, label: u.name })), l.assignedTo) + '</select></div>' +
      '<div style="min-width:120px"><span class="l">Priority</span><select class="in" name="priority">' + opts(db().config.priorities, l.priority) + '</select></div>' +
      '<div style="min-width:120px"><span class="l">Type</span><select class="in" name="type">' + opts(db().config.leadTypes, l.type) + '</select></div>' +
      '<div style="min-width:170px"><span class="l">Status</span><select class="in" name="status" aria-label="Status" data-search>' + opts(STAGES.concat(isClosed ? [l.status] : []), l.status) + '</select>' + (isClosed ? '<span style="font-size:11.5px;color:var(--bad-fg)">Closed as ' + esc(l.status) + '</span>' : '') + '</div>' +
      '<div style="flex:1 1 100%;min-width:200px"><span class="l">Open tasks</span><div style="display:flex;flex-direction:column;gap:6px">' + (tasks.slice(0, 2).map((x) => '<label style="display:flex;gap:8px;align-items:center;font-size:12.5px"><input type="checkbox" data-task="' + x.id + '" style="accent-color:var(--purple)"><span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(x.title) + '</span><span style="color:' + (Store.isOverdue(x) ? 'var(--bad-fg)' : 'var(--muted)') + ';font-size:11.5px;white-space:nowrap">' + fmtDate(x.due) + '</span></label>').join('') || '<span style="font-size:12.5px;color:var(--muted)">None</span>') + (tasks.length > 2 ? '<a href="#/tasks" style="font-size:12px">+' + (tasks.length - 2) + ' more</a>' : '') + '<button class="btn xs" data-act="task" style="align-self:flex-start">+ Task</button></div></div></div>';

    const composer = '<section class="card flush composer" id="composer"><div class="tabs" style="padding:0 18px">' + [['email', 'mailC', 'Email'], ['call', 'phoneC', 'Call note'], ['meeting', 'calC', 'Meeting'], ['research', 'bookC', 'Research note']].map(([k, ic, lab]) => '<button class="tab' + (k === 'email' ? ' on' : '') + '" data-ctab="' + k + '"><span class="ctab">' + I[ic] + lab + '</span></button>').join('') + '</div>' +
      '<div class="body" data-cpanel="email"><div class="grid2"><div><label class="lbl">To</label><input class="in" name="to" value="' + esc(email) + '" placeholder="' + (email ? '' : 'No email on file – add a contact') + '"></div><div><label class="lbl">Project</label><select class="in" name="project" aria-label="Project"' + (c && c.isClient ? '' : ' disabled') + '>' + opts(Store.projectsFor(l.companyId).map((x) => ({ value: x.id, label: x.id + ' · ' + x.name })), (Store.projectsFor(l.companyId).find((x) => x.leadId === id) || {}).id || '', c && c.isClient ? (Store.projectsFor(l.companyId).length ? '— no project —' : 'no projects yet') : 'available once the lead is Won') + '</select></div>' + (contacts.filter((k) => k.email && k.email !== email).length ? '<div class="span2"><div class="lbl">Cc stakeholders</div><div style="display:flex;gap:6px 14px;flex-wrap:wrap">' + contacts.filter((k) => k.email && k.email !== email).map((k) => '<label class="sw" style="font-size:12.5px"><input type="checkbox" data-sh="' + esc(k.email) + '"' + (((Store.projectsFor(l.companyId).find((x) => x.leadId === id) || { stakeholders: Store.primaryStakeholders(l.companyId) }).stakeholders || []).includes(k.id) ? ' checked' : '') + '> ' + esc(k.firstName + ' ' + k.lastName) + ' <span style="color:var(--muted)">· ' + esc(k.designation || k.type) + '</span></label>').join('') + '</div></div>' : '') + '<div><label class="lbl">Template</label><select class="in" name="tpl"><option value="">— blank —</option>' + Store.templatesFor(me.lang || 'en').map((x) => '<option value="' + x.id + '">' + esc(x.name) + (x.source === 'oft' ? ' · .oft' : '') + (x.lang !== (me.lang || 'en') ? ' (' + x.lang.toUpperCase() + ')' : '') + '</option>').join('') + '</select></div><div class="span2"><label class="lbl">Subject</label><input class="in" name="subject" value="' + esc(fill(TPL.intro[0])) + '"></div><div class="span2"><label class="lbl">Message</label><textarea class="in" name="body" rows="7">' + esc(fill(TPL.intro[1])) + '</textarea></div></div><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><label class="sw" style="font-size:12.5px"><input type="checkbox" name="setFollow" checked> Set follow-up in <select class="in" name="followDays" style="width:90px;height:28px;display:inline-block;margin:0 4px"><option value="2">2 days</option><option value="3" selected>3 days</option><option value="7">1 week</option></select></label><div class="grow"></div><button class="btn primary" data-send="email">' + I.send + 'Send email</button></div></div>' +
      '<div class="body" data-cpanel="call" hidden><div class="grid3"><div><label class="lbl">Outcome</label><select class="in" name="outcome"><option>Connected</option><option>No answer</option><option>Left voicemail</option><option>Call back later</option></select></div><div><label class="lbl">Duration (min)</label><input class="in" name="minutes" type="number" min="0" value="10"></div><div><label class="lbl">Status after call</label><select class="in" name="statusAfter">' + opts(db().config.leadStatuses, l.status) + '</select></div><div class="span3"><label class="lbl">What was discussed</label><textarea class="in" name="callNotes" rows="4" placeholder="Key points, objections, next step agreed…"></textarea></div><div><label class="lbl">Next follow-up</label><input class="in" type="date" name="callFollow" value="' + Store.addDays(t, 3) + '"></div></div><div style="display:flex;justify-content:flex-end"><button class="btn primary" data-send="call">Save call</button></div></div>' +
      '<div class="body" data-cpanel="meeting" hidden><div class="grid3"><div class="span3"><label class="lbl">Title</label><input class="in" name="mtitle" value="' + esc('Meeting · ' + l.companyName) + '"></div><div><label class="lbl">Date</label><input class="in" type="date" name="mdate" value="' + Store.addDays(t, 2) + '"></div><div><label class="lbl">Time</label><input class="in" name="mtime" value="10:00"></div><div><label class="lbl">Length</label><select class="in" name="mlen"><option value="30">30 min</option><option value="60" selected>1 hour</option><option value="90">1.5 hours</option></select></div><div class="span2"><label class="lbl">Where</label><input class="in" name="mwhere" value="Microsoft Teams"></div><div><label class="lbl">Also invite</label><select class="in" name="minvite"><option value="">— just me —</option>' + opts(db().users.filter((u) => u.id !== me.id).map((u) => ({ value: u.id, label: u.name }))) + '</select></div></div><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><span style="font-size:12.5px;color:var(--muted)">Invite goes to ' + esc(ct ? ct.firstName + ' ' + ct.lastName : 'the contact') + (email ? ' (' + esc(email) + ')' : '') + '. Appears on the calendar and the timeline.</span><div class="grow"></div><button class="btn primary" data-send="meeting">Schedule</button></div></div>' +
      '<div class="body" data-cpanel="research" hidden><div class="note ai" style="font-size:12.5px">Save anything you found outside the CRM: LinkedIn, news, annual reports, competitor notes. Saved against this lead and listed as a research source on the company.</div><div class="grid2"><div><label class="lbl">Title</label><input class="in" name="rtitle" placeholder="e.g. LinkedIn: new CFO appointed"></div><div><label class="lbl">Link (optional)</label><input class="in" name="rurl" type="url" placeholder="https://"></div><div class="span2"><label class="lbl">Notes</label><textarea class="in" name="rbody" rows="5" placeholder="What did you learn, and why does it matter for this deal?"></textarea></div></div><div style="display:flex;justify-content:flex-end"><button class="btn primary" data-send="research">Save research</button></div></div></section>';

    const tl = '<!--l2:tl--><section class="card flush"><div class="tabs" style="padding:0 18px">' + FILTERS.map(([k, lab, n]) => '<a class="tab' + (tab === k ? ' on' : '') + '" href="#/leads/' + id + '/' + k + '">' + lab + ' <span class="n">' + n + '</span></a>').join('') + '</div><div style="padding:18px 20px 6px"><!--l2:tlb-->' + timeline(shown) + '<!--/l2:tlb--></div></section>';

    const contactCard = '<section class="card" style="gap:10px"><div style="display:flex;align-items:center;gap:12px">' + (ct ? '<span class="av" style="width:44px;height:44px;font-size:14px">' + esc(UI.initials(ct.firstName + ' ' + ct.lastName)) + '</span><div style="min-width:0"><div style="font-weight:700;font-size:14px;white-space:nowrap">' + esc(ct.firstName + ' ' + ct.lastName) + '</div><div style="font-size:12.5px;color:var(--muted)">' + esc(ct.designation || '') + (ct.department ? ' · ' + esc(ct.department) : '') + ' · ' + badge(ct.type) + '</div></div>' : '<div style="font-weight:700;font-size:14px">No contact yet</div><div class="grow"></div><button class="btn sm primary" data-act="addcontact">Add contact</button>') + '</div>' +
      (ct || email || phone ? '<div><div class="crow"><span class="k">Email</span><span class="v">' + (email ? esc(email) : '<span class="dim">—</span>') + '</span>' + (email ? '<button class="btn xs act" data-compose="email">Write</button>' : '') + '</div><div class="crow"><span class="k">Phone</span><span class="v">' + (phone ? '<a href="tel:' + esc(phone.replace(/\s/g, '')) + '">' + esc(phone) + '</a>' : '<span class="dim">—</span>') + '</span>' + (phone ? '<button class="btn xs act" data-compose="call">Log call</button>' : '') + '</div><div class="crow"><span class="k">LinkedIn</span><span class="v">' + (ct && ct.linkedin ? '<a href="' + UI.href(ct.linkedin) + '" target="_blank" rel="noopener">View profile ↗</a>' : '<span class="dim">—</span>') + '</span></div></div>' : '') +
      (contacts.length > 1 ? '<div><label class="lbl" style="margin-bottom:4px">Switch contact</label><select class="in" name="contactId" style="height:32px">' + opts(contacts.map((x) => ({ value: x.id, label: x.firstName + ' ' + x.lastName + ' · ' + (x.designation || x.type) })), l.contactId) + '</select></div>' : '') + (ct ? '<button class="btn xs" data-act="addcontact" style="align-self:flex-start">+ Another contact</button>' : '') + '</section>';

    const companyCard = c ? '<section class="card" style="gap:10px"><div style="display:flex;align-items:center;gap:12px">' + UI.logo(c.name) + '<div style="min-width:0"><a href="#/companies/' + c.id + '" style="font-weight:700;font-size:14px;color:var(--text)">' + esc(c.legalName || c.name) + '</a><div style="font-size:12.5px;color:var(--muted)">' + esc(c.industry || 'Industry unknown') + ' · ' + esc([c.city, c.country].filter(Boolean).join(', ')) + (c.employeeRange ? ' · ' + c.employeeRange + ' staff' : '') + '</div></div></div>' + (c.ai.summary ? '<div class="note ai" style="font-size:12.5px"><strong>AI summary</strong> <span class="tag-ai" style="margin-left:4px">' + esc(c.ai.confidence || '') + '</span><div style="margin-top:4px">' + esc(c.ai.summary) + '</div></div>' : '<div class="note info">No AI research yet. <a href="#/companies/' + c.id + '/ai">Run research</a></div>') + '<div style="display:flex;gap:14px;font-size:12.5px;color:var(--muted);flex-wrap:wrap"><span>' + badge(c.ai.verification) + '</span>' + (c.website ? '<a href="' + UI.href(c.website) + '" target="_blank" rel="noopener">' + esc(c.domain) + ' ↗</a>' : '') + '<span>' + others.length + ' other lead' + (others.length === 1 ? '' : 's') + '</span><a href="#/companies/' + c.id + '">Full profile →</a></div></section>' : '';

    const side2 = (c ? V.projectsCard(c.id, id) : '') + '<!--l2:rs--><section class="card" style="gap:10px"><div style="display:flex;align-items:center;justify-content:space-between"><h2>Research &amp; links</h2><button class="btn xs" data-compose="research">+ Add</button></div>' + (research.slice(0, 4).map((a) => '<div class="rnote"><strong>' + esc(a.title.replace(/^Research · /, '')) + '</strong><span style="color:var(--body)">' + esc((a.body || '').slice(0, 120)) + ((a.body || '').length > 120 ? '…' : '') + '</span>' + (a.url ? '<a href="' + UI.href(a.url) + '" target="_blank" rel="noopener">' + esc(a.url.replace(/^https?:\/\//, '')) + ' ↗</a>' : '') + '<span style="display:block;color:var(--muted);font-size:11.5px;margin-top:3px">' + esc(Store.userName(a.by)) + ' · ' + rel(a.at) + '</span></div>').join('') || '<div style="font-size:12.5px;color:var(--muted)">Nothing saved yet. Use the Research note tab to keep findings from LinkedIn, news or reports here.</div>') + '</section><!--/l2:rs-->' +
      (events.length || quotes.length ? '<section class="card" style="gap:8px"><h2>Coming up</h2>' + events.map((e) => '<a class="link" href="#/calendar?week=' + e.date + '"><span>' + I.calS.replace('<svg', '<svg style="width:14px;height:14px;vertical-align:-2px;margin-right:6px"') + esc(e.title) + '</span><span style="color:var(--muted)">' + fmtDate(e.date) + ' ' + e.start + '</span></a>').join('') + quotes.map((x) => '<a class="link" href="#/quotes/' + x.id + '"><span>' + x.id + ' · ' + Store.fmtMoney(Store.quoteTotals(x).total, x.currency) + '</span>' + badge(x.status) + '</a>').join('') + '</section>' : '') +
      (enq ? '<section class="card" style="gap:8px"><h2>Original enquiry <span class="badge b-grey">read only</span></h2><div style="font-size:12.5px;color:var(--body);line-height:1.5">"' + esc(enq.message) + '"</div><div style="font-size:12px;color:var(--muted)">' + fmtDT(enq.submittedAt) + ' · <a href="#/enquiries/' + enq.id + '">' + enq.id + '</a></div></section>' : '') +
      '<details class="card" style="gap:8px"><summary style="cursor:pointer;font-weight:700;font-size:13px">Details</summary><dl class="kv" style="grid-template-columns:110px 1fr;margin-top:8px"><dt>Lead ID</dt><dd>' + id + '</dd><dt>Source</dt><dd>' + esc(l.source) + (l.importBatch ? ' · #' + esc(l.importBatch) : '') + '</dd><dt>Source URL</dt><dd>' + (l.sourceUrl ? '<a href="' + UI.href(l.sourceUrl) + '" target="_blank" rel="noopener">' + esc(l.sourceUrl.replace(/^https?:\/\//, '')) + '</a>' : '—') + '</dd><dt>Website</dt><dd>' + (l.website ? esc(Store.domainOf(l.website)) : '—') + '</dd><dt>Created</dt><dd>' + fmtDT(l.createdAt) + '</dd><dt>AI enrichment</dt><dd>' + badge(l.enrichment) + '</dd><dt>Notes</dt><dd style="font-weight:400">' + (l.notes ? esc(l.notes) : '—') + '</dd></dl><div style="display:flex;gap:8px;margin-top:8px"><button class="btn xs" data-act="edit">Edit</button><button class="btn xs" data-act="archive">' + (l.archived ? 'Unarchive' : 'Archive') + '</button></div></details>';

    const html = header + '<div class="page"><!--l2:top--><section class="card" style="gap:18px"><!--l2:st-->' + stepper + '<!--/l2:st--><!--l2:ctrl-->' + ctrl + '<!--/l2:ctrl--></section><div class="cols"><div class="col-main">' + composer + tl + '</div><aside class="col-side" style="max-width:360px"><!--l2:cc-->' + contactCard + '<!--/l2:cc--><!--l2:co-->' + companyCard + '<!--/l2:co-->' + side2 + '</aside></div></div>';

    return { html, mount(el) {
      const act = (name, fn) => el.querySelectorAll('[data-act=' + name + ']').forEach((b) => b.addEventListener('click', fn));
      const panel = (k) => { el.querySelectorAll('[data-cpanel]').forEach((p) => { p.hidden = p.dataset.cpanel !== k; }); el.querySelectorAll('[data-ctab]').forEach((b) => b.classList.toggle('on', b.dataset.ctab === k)); const first = el.querySelector('[data-cpanel=' + k + '] input,[data-cpanel=' + k + '] textarea'); if (first) first.focus(); el.querySelector('#composer').scrollIntoView({ behavior: 'smooth', block: 'nearest' }); };
      el.querySelectorAll('[data-ctab]').forEach((b) => b.addEventListener('click', () => panel(b.dataset.ctab)));
      el.querySelectorAll('[data-compose]').forEach((b) => b.addEventListener('click', () => panel(b.dataset.compose)));
      // status pipeline
      el.querySelectorAll('[data-stage]').forEach((b) => b.addEventListener('click', () => { const s = b.dataset.stage; if (s === l.status) return; if (s === 'Won') { modal('<h2>Mark ' + id + ' as Won?</h2><p style="margin:0;font-size:13px;color:var(--body)">The lead closes as Won and ' + esc(l.companyName) + ' is flagged as a client. The follow-up date and open tasks on this lead are closed. A client can have several projects, so the project is created as a separate step.</p><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn" data-go="won">Mark Won</button><button class="btn primary" data-go="project">Mark Won and create project</button></div>', (bg, close) => bg.querySelectorAll('[data-go]').forEach((b) => b.addEventListener('click', () => { const withProject = b.dataset.go === 'project'; close(); Store.convertLead(id); toast(id + ' won · ' + (c ? c.name : l.companyName) + ' is now a client'); if (withProject) V.projectModal({ companyId: l.companyId, leadId: id }); }))); return; } Store.updateLead(id, { status: s }); toast('Status → ' + s); }));
      act('close', () => modal('<h2>Close ' + id + '</h2><div><label class="lbl">Outcome</label><select class="in" name="status"><option>Lost</option><option>Not Relevant</option></select></div><div><label class="lbl">Reason</label><textarea class="in" name="note" rows="3" placeholder="Budget, timing, competitor, wrong fit…"></textarea></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-go>Close lead</button></div>', (bg, close) => bg.querySelector('[data-go]').addEventListener('click', () => { const d = form(bg); Store.updateLead(id, { status: d.status, note: d.note }); close(); toast(id + ' closed as ' + d.status); })));
      // control strip
      const fu = el.querySelector('[name=followUp]'); fu.addEventListener('change', () => { Store.updateLead(id, { followUp: fu.value || null }); toast(fu.value ? 'Follow-up set · task updated' : 'Follow-up cleared'); });
      el.querySelectorAll('[data-q]').forEach((b) => b.addEventListener('click', () => { const d = Store.addDays(t, Number(b.dataset.q)); Store.updateLead(id, { followUp: d }); toast('Follow-up ' + fmtDate(d) + ' · task created'); }));
      el.querySelector('[name=assignedTo]').addEventListener('change', (e) => { const to = e.target.value; if (!to) { Store.updateLead(id, { assignedTo: null }); return; } modal('<h2>Transfer to ' + esc(Store.userName(to)) + '</h2><div><label class="lbl">Transfer note <span class="req">*</span></label><textarea class="in" name="note" rows="3" placeholder="Why is this lead moving?"></textarea></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-go>Transfer</button></div>', (bg, close) => { bg.querySelector('[data-go]').addEventListener('click', () => { const n = bg.querySelector('[name=note]').value.trim(); if (!n) { toast('A transfer note is required', 'warn'); return; } Store.transferLead(id, to, n); close(); toast('Transferred · ' + Store.userName(to) + ' notified'); }); bg.addEventListener('click', (ev) => { if (ev.target.closest('[data-close]') || ev.target === bg) e.target.value = l.assignedTo || ''; }); }); });
      el.querySelector('[name=status]').addEventListener('change', (e) => { const s = e.target.value; if (s === l.status) return; if (s === 'Won') { const w = el.querySelector('[data-stage=Won]'); if (w) { w.click(); e.target.value = l.status; return; } Store.convertLead(id); toast(id + ' won · client created'); return; } Store.updateLead(id, { status: s }); toast('Status → ' + s); });
      el.querySelector('[name=priority]').addEventListener('change', (e) => { Store.updateLead(id, { priority: e.target.value }); });
      el.querySelector('[name=type]').addEventListener('change', (e) => { Store.updateLead(id, { type: e.target.value }); });
      el.querySelectorAll('[data-task]').forEach((cb) => cb.addEventListener('change', () => { Store.toggleTask(cb.dataset.task); toast('Task done'); }));
      const cs = el.querySelector('[name=contactId]'); if (cs) cs.addEventListener('change', () => { const x = Store.contact(cs.value); Store.updateLead(id, { contactId: cs.value, email: x.email || l.email, phone: x.mobile || x.phone || l.phone }); });
      // composer: email
      const tplSel = el.querySelector('[name=tpl]'); tplSel.addEventListener('change', () => { const T = (db().templates || []).find((x) => x.id === tplSel.value); const ctx = { first_name: first, company: l.companyName, me: me.name, lead_id: id, quote_no: '' }; el.querySelector('[name=subject]').value = T ? Store.fillTemplate(T.subject, ctx) : ''; el.querySelector('[name=body]').value = T ? Store.fillTemplate(T.body, ctx) : ''; });
      el.querySelector('[data-send=email]').addEventListener('click', () => { const to = el.querySelector('[name=to]').value.trim(); const subject = el.querySelector('[name=subject]').value.trim(); const body = el.querySelector('[name=body]').value; if (!to || !subject) { toast('Add a recipient and a subject', 'warn'); return; } const cc = [...el.querySelectorAll('[data-cpanel=email] [data-sh]:checked')].map((x) => x.dataset.sh).join(', '); const projectId = el.querySelector('[name=project]').value || null; Store.sendEmail({ to, cc, subject, body, leadId: id, contactId: l.contactId, companyId: l.companyId, projectId }); const patch = {}; if (el.querySelector('[name=setFollow]').checked) patch.followUp = Store.addDays(t, Number(el.querySelector('[name=followDays]').value)); if (l.status === 'New' || l.status === 'Not Contacted') patch.status = 'Contacted'; if (Object.keys(patch).length) Store.updateLead(id, patch); if (Store.accountFor(me.id)) toast('Email sent to ' + to + (patch.followUp ? ' · follow-up ' + fmtDate(patch.followUp) : '')); else toast('Email logged on ' + id + ' · not sent: connect your mailbox in Settings', 'warn'); });
      el.querySelector('[data-send=call]').addEventListener('click', () => { const g = (n) => el.querySelector('[name=' + n + ']').value; if (!g('callNotes').trim() && g('outcome') === 'Connected') { toast('Add a line about what was discussed', 'warn'); return; } Store.logCall(id, g('outcome'), g('minutes'), g('callNotes').trim(), g('statusAfter'), g('callFollow') || null); toast('Call saved' + (g('statusAfter') !== l.status ? ' · status → ' + g('statusAfter') : '')); });
      el.querySelector('[data-send=meeting]').addEventListener('click', () => { const g = (n) => el.querySelector('[name=' + n + ']').value; const [h, m] = g('mtime').split(':').map(Number); const endM = h * 60 + m + Number(g('mlen')); const end = String(Math.floor(endM / 60)).padStart(2, '0') + ':' + String(endM % 60).padStart(2, '0'); const inv = g('minvite'); Store.createEvent({ title: g('mtitle'), type: 'meeting', date: g('mdate'), start: g('mtime'), end, leadId: id, companyId: l.companyId, contactId: l.contactId, attendees: [ct ? ct.firstName + ' ' + ct.lastName : l.companyName, me.name].concat(inv ? [Store.userName(inv)] : []).join(', '), attendeeIds: inv ? [inv] : [], where: g('mwhere'), note: 'Invite sent' }); Store.updateLead(id, { followUp: g('mdate') }); toast('Meeting scheduled · invite sent · follow-up set to ' + fmtDate(g('mdate'))); });
      el.querySelector('[data-send=research]').addEventListener('click', () => { const g = (n) => el.querySelector('[name=' + n + ']').value.trim(); if (!g('rtitle')) { toast('Give the research a title', 'warn'); return; } Store.saveResearch(id, g('rtitle'), g('rurl') || null, g('rbody')); toast('Research saved on ' + id + (l.companyId ? ' and listed under company sources' : '')); location.hash = '#/leads/' + id + '/research'; });
      // misc
      act('task', () => modal('<h2>New task</h2><div><label class="lbl">Title</label><input class="in" name="title" value="Follow up · ' + esc(l.companyName) + '"></div><div class="grid2"><div><label class="lbl">Due</label><input class="in" type="date" name="due" value="' + Store.addDays(t, 1) + '"></div><div><label class="lbl">Assigned to</label><select class="in" name="assignedTo">' + opts(db().users.map((u) => ({ value: u.id, label: u.name })), l.assignedTo || me.id) + '</select></div></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-go>Create</button></div>', (bg, close) => bg.querySelector('[data-go]').addEventListener('click', () => { const d = form(bg); Store.createTask(id, d.title, d.due, d.assignedTo); close(); toast('Task created'); })));
      act('newproject', () => V.projectModal({ companyId: l.companyId, leadId: id }));
      act('addcontact', () => { if (!l.companyId) { toast('Link a company first (Edit)', 'warn'); return; } V.contactModal(l.companyId); });
      act('archive', () => { if (l.archived) { Store.updateLead(id, { archived: false }); toast('Lead restored'); return; } modal('<h2>Archive ' + id + '?</h2><p style="margin:0;font-size:13px;color:var(--body)">The lead disappears from lists and counts. Its history is kept and you can unarchive it from this page.</p><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-go>Archive</button></div>', (bg, close) => bg.querySelector('[data-go]').addEventListener('click', () => { close(); Store.updateLead(id, { archived: true }); toast('Lead archived'); })); });
      act('edit', () => modal('<h2>Edit lead</h2><div class="grid2"><div><label class="lbl">Company name</label><input class="in" name="companyName" value="' + esc(l.companyName) + '"></div><div><label class="lbl">Country</label><select class="in" name="country">' + opts(db().config.countries, l.country) + '</select></div><div><label class="lbl">Business email</label><input class="in" name="email" value="' + esc(l.email || '') + '"></div><div><label class="lbl">Phone</label><input class="in" name="phone" value="' + esc(l.phone || '') + '"></div><div><label class="lbl">Website</label><input class="in" name="website" value="' + esc(l.website || '') + '"></div><div><label class="lbl">Source</label><select class="in" name="source">' + opts(db().config.leadSources, l.source) + '</select></div><div class="span2"><label class="lbl">Notes</label><textarea class="in" name="notes" rows="3">' + esc(l.notes || '') + '</textarea></div></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-go>Save</button></div>', (bg, close) => bg.querySelector('[data-go]').addEventListener('click', () => { const d = form(bg); Store.updateLead(id, { companyName: d.companyName, country: d.country, email: d.email || null, phone: d.phone || null, website: d.website || null, source: d.source, notes: d.notes || null }); close(); toast('Saved'); })));
      act('clone', () => modal('<h2>Clone ' + id + '?</h2><p style="margin:0;font-size:13px;color:var(--muted)">Creates a new lead for ' + esc(l.companyName) + (ct ? ' · ' + esc(ct.firstName + ' ' + ct.lastName) : '') + ' with the same details and owner. It starts at status New. Activity, tasks and quotations stay on ' + id + '.</p><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-go>Clone lead</button></div>', (bg, close) => bg.querySelector('[data-go]').addEventListener('click', () => { const n = Store.cloneLead(id); close(); toast('Cloned · ' + n.id + ' created from ' + id); location.hash = '#/leads/' + n.id; })));
    } };
  };
})();
